added = 0
for description, content in CELLS:
    cid = bridge.save_cell(
        description=description,
        content=content,
        source_table='identity',
        confidence=0.97,
        energy=180.0,
    )
    print(f"  + {cid[:38]}  {description[:50]!r}")
    added += 1

print(f"\nDone. {added} identity cells seeded.")
